class HrmPayrollWageRecoveryServiceTest extends BaseDbUnitTest {
 @Resource HrmPayrollWageRecoveryService service;
 @Resource HrmPayrollRetroService retro;
 @Resource HrmPayrollWageRecoveryMapper recoveries;
 @Resource HrmPayrollWageRecoveryEventMapper events;
 @Resource HrmPayrollRetroMapper retros;
 @Resource HrmPayrollTaxCorrectionMapper corrections;
 @Resource HrmPayrollTaxPolicyMapper policies;
 @Resource HrmPayrollPaymentMapper payments;
 @Resource HrmPayrollRunMapper runs;
 @Resource HrmEmployeeMapper employees;
 @Resource HrmSalaryMonthRecordMapper batches;
 @MockBean HrmPayrollScopeService scope;
 @MockBean HrmPayrollEntityService entities;
 @MockBean HrmPayrollTaxProfileService profiles;
 HrmSalaryMonthRecordDO original;HrmPayrollPaymentDO payment;HrmPayrollRunDO run;HrmPayrollTaxCorrectionDO correction;Long employeeId;HrmPayrollTaxPolicyDO policy;
 BigDecimal n(String value){return new BigDecimal(value);}
 LocalDate today(){return LocalDate.now(ZoneId.of("Asia/Shanghai"));}
 HrmSalaryMonthEmployeeRecordDO salary(String income,String net,int year){List<HrmSalaryMonthEmployeeRecordDO.OptionValue> values=new ArrayList<>();int[] codes={250101,270101,250102,270102,250103,270103};String[] amounts={"0",income,"0","5000","0","1000"};for(int i=0;i<codes.length;i++)values.add(new HrmSalaryMonthEmployeeRecordDO.OptionValue().setCode(codes[i]).setValue(n(amounts[i])));HrmPayrollTaxWithholdingService.Source source=new HrmPayrollTaxWithholdingService.Source().setEntityId(10L).setEmployeeId(employeeId).setCurrentIncome(n(income)).setCurrentSocialDeduction(n("1000")).setExpectedPaymentDate(LocalDate.of(year,9,30)).setProfile(new HrmPayrollTaxProfileDO().setId(100L).setTaxpayerKey("recovery-person").setTaxRegistrationNumber("tax-agent")).setQuote(new PayrollTaxPolicyEngine.Quote().setCurrentSalaryWithholding(n("100")).setCurrentWithholding(n("100")).setSeparateBonusTax(BigDecimal.ZERO));return new HrmSalaryMonthEmployeeRecordDO().setEmployeeId(employeeId).setExpectedPaySalary(n(income)).setRealPaySalary(n(net)).setPersonalTax(n("100")).setOptionValues(values).setTaxSourceSnapshot(JsonUtils.toJsonString(source));}
 @BeforeEach void setup(){HrmEmployeeDO employee=new HrmEmployeeDO().setName("已离职收回员工").setUserId(99L).setJobNumber("REC-1").setLeaveTime(LocalDate.of(2025,9,30).atStartOfDay());employees.insert(employee);employeeId=employee.getId();original=new HrmSalaryMonthRecordDO().setEntityId(10L).setTitle("2025年9月原工资").setYear(2025).setMonth(9).setBatchKey("REGULAR").setStatus(17).setStartTime(LocalDate.of(2025,9,1).atStartOfDay()).setEndTime(LocalDate.of(2025,9,30).atStartOfDay());batches.insert(original);run=new HrmPayrollRunDO().setMonthRecordId(original.getId()).setVersion(1).setInputSnapshot("{}").setRuleSnapshot("{}").setResultSnapshot(JsonUtils.toJsonString(Collections.singletonList(salary("10000","8900",2025))));runs.insert(run);payment=new HrmPayrollPaymentDO().setMonthRecordId(original.getId()).setRunId(run.getId()).setEmployeeId(employeeId).setEmployeeName("已离职收回员工").setBankAccount("test-bank-fact").setAmount(n("8900")).setStatus("SUCCESS").setAttempt(1).setValueDate(LocalDate.of(2025,9,30));payments.insert(payment);payment=payments.selectById(payment.getId());
  policy=new HrmPayrollTaxPolicyDO().setEntityId(10L).setYear(2025).setTaxRegistrationNumber("tax-agent").setStatus("APPROVED").setVersion(1);policies.insert(policy);when(profiles.requireApproved(eq(10L),eq(employeeId),anyInt())).thenAnswer(call->new HrmPayrollTaxProfileDO().setId(100L).setVersion(1).setTaxpayerKey("recovery-person").setTaxRegistrationNumber("tax-agent").setYear(call.getArgument(2)));
  correction=new HrmPayrollTaxCorrectionDO().setPaymentId(payment.getId()).setEntityId(10L).setEmployeeId(employeeId).setRunId(run.getId()).setVersion(1).setPolicyId(policy.getId()).setPolicyVersion(1).setProfileId(100L).setProfileVersion(1).setTaxpayerKey("recovery-person").setTaxRegistrationNumber("tax-agent").setStatus("APPROVED").setIncome(n("8000")).setSocialDeduction(n("1000")).setBasicDeduction(n("5000")).setActualSalaryWithheld(n("100")).setSeparateBonusIncome(BigDecimal.ZERO).setActualBonusWithheld(BigDecimal.ZERO).setValueDate(payment.getValueDate()).setSourceDigest(HrmPayrollTaxCorrectionService.digest(payment,run));corrections.insert(correction);
  when(scope.payrollDates(any())).thenReturn(Collections.singletonMap(employeeId,Collections.singleton(LocalDate.of(2026,10,1))));
 }
 HrmPayrollWageRecoveryReqVO req(){return new HrmPayrollWageRecoveryReqVO().setPaymentId(payment.getId()).setCorrectedIncome(n("8000")).setTaxCorrectionIds(Collections.singletonList(correction.getId())).setEmployeeAcknowledgement("员工确认原年度税前多发工资及税款另行处理").setEvidence("正式核定及退款依据").setRequestKey(UUID.randomUUID().toString());}
 Long approved(){Long id=service.create(req(),1L);service.review(id,true,"独立核实原工资、员工确认和税务分配",2L);return id;}
 HrmPayrollWageRecoveryActionReqVO receipt(Long id){return new HrmPayrollWageRecoveryActionReqVO().setId(id).setAmount(n("2000")).setValueDate(today()).setReference("recovery-receipt-001").setEvidence("真实收款凭证编号");}
 HrmSalaryMonthRecordDO target(){HrmSalaryMonthRecordDO b=new HrmSalaryMonthRecordDO().setEntityId(10L).setYear(2026).setMonth(10).setBatchKey("REGULAR").setStatus(5).setStartTime(LocalDate.of(2026,10,1).atStartOfDay()).setEndTime(LocalDate.of(2026,10,31).atStartOfDay()).setExpectedPaymentDate(today());batches.insert(b);return b;}
 @Test void departedEmployeeCrossYearRecoveryKeepsOriginalCashAndWagesImmutable(){String frozen=run.getResultSnapshot();Long id=approved();service.confirm(receipt(id),3L);HrmPayrollWageRecoveryDO row=recoveries.selectById(id);assertEquals("SETTLED",row.getStatus());assertEquals(today(),row.getValueDate());List<HrmPayrollWageRecoveryService.Allocation> allocation=JsonUtils.parseArray(row.getAllocationSnapshot(),HrmPayrollWageRecoveryService.Allocation.class);assertEquals(2025,allocation.get(0).getCashYear());assertEquals(0,n("2000").compareTo(row.getAmount()));assertEquals(0,n("8900").compareTo(payments.selectById(payment.getId()).getAmount()));assertEquals(frozen,runs.selectById(run.getId()).getResultSnapshot());assertTrue(retro.sources(original.getId()).isEmpty());assertTrue(retro.list(original.getId(),1L).isEmpty());assertEquals(3,service.history(id,1L).size());}
 @Test void noUnconfirmedRecoveryCanBecomeAnotherEntitlementBaseline(){Long id=approved();HrmPayrollRetroDO first=retros.selectById(recoveries.selectById(id).getRetroId());assertServiceException(()->retro.baseline(payment,first),PAYROLL_RECOVERY_INVALID);service.confirm(receipt(id),3L);assertEquals(0,n("8000").compareTo(retro.baseline(payment,first)));assertEquals(0,n("8000").compareTo((BigDecimal)service.baseline(payment.getId(),1L).get("income")));}
 @Test void makerEmployeeAndReviewerCannotConfirmTheirOwnReceipt(){Long id=service.create(req(),1L);assertServiceException(()->service.review(id,true,"本人",1L),PAYROLL_SELF_APPROVAL);assertServiceException(()->service.review(id,true,"员工",99L),PAYROLL_SELF_APPROVAL);service.review(id,true,"独立复核",2L);assertServiceException(()->service.confirm(receipt(id),1L),PAYROLL_SELF_APPROVAL);assertServiceException(()->service.confirm(receipt(id),2L),PAYROLL_SELF_APPROVAL);assertServiceException(()->service.confirm(receipt(id),99L),PAYROLL_SELF_APPROVAL);}
 @Test void exactReceiptRetriesAreIdempotentAndAmountsDatesCannotChange(){Long id=approved();assertServiceException(()->service.confirm(receipt(id).setAmount(n("1999")),3L),PAYROLL_RECOVERY_INVALID);assertServiceException(()->service.confirm(receipt(id).setValueDate(today().plusDays(1)),3L),PAYROLL_RECOVERY_INVALID);service.confirm(receipt(id),3L);service.confirm(receipt(id),3L);assertEquals(3,events.selectCount());assertServiceException(()->service.confirm(receipt(id).setReference("changed"),3L),PAYROLL_VERSION_CONFLICT);assertServiceException(()->service.cancel(id,"已结清不能撤销","作废",4L),PAYROLL_RECOVERY_INVALID);}
 @Test void requestReplayIsImmutableAndSameTaxAmendmentCannotFundTwoCases(){HrmPayrollWageRecoveryReqVO r=req();Long id=service.create(r,1L);assertEquals(id,service.create(r,1L));assertServiceException(()->service.create(r.setEvidence("换依据"),1L),PAYROLL_RECOVERY_INVALID);assertServiceException(()->service.create(req(),1L),PAYROLL_RECOVERY_INVALID);}
 @Test void allocationMustBeApprovedRelatedAndExactAndExplicitZeroCannotCreateARefund(){assertServiceException(()->service.create(req().setCorrectedIncome(n("8500")),1L),PAYROLL_RECOVERY_INVALID);assertServiceException(()->service.create(req().setTaxCorrectionIds(Arrays.asList(correction.getId(),correction.getId())),1L),PAYROLL_RECOVERY_INVALID);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setStatus("PENDING"));assertServiceException(()->service.create(req(),1L),PAYROLL_RECOVERY_INVALID);assertServiceException(()->service.create(req().setCorrectedIncome(n("10000")),1L),PAYROLL_RECOVERY_INVALID);assertServiceException(()->service.create(req().setCorrectedIncome(n("-1")),1L),PAYROLL_RECOVERY_INVALID);}
 @Test void changedTaxAmendmentBeforeReviewOrReceiptRequiresNewCase(){Long id=service.create(req(),1L);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setStatus("SUPERSEDED"));assertServiceException(()->service.review(id,true,"来源已变化",2L),PAYROLL_RECOVERY_INVALID);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setStatus("APPROVED"));service.review(id,true,"重新核实",2L);payments.updateById(new HrmPayrollPaymentDO().setId(payment.getId()).setAmount(n("8899")));assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.confirm(receipt(id),3L));assertEquals("APPROVED",recoveries.selectById(id).getStatus());}
 @Test void cancellationRequiresVoidEvidenceAndReleasesOnlyUnsettledAllocation(){Long id=approved();assertServiceException(()->service.cancel(id,"撤销",null,3L),PAYROLL_RECOVERY_INVALID);service.cancel(id,"核定撤回","原退款指令已作废",3L);assertEquals("CANCELLED",retros.selectById(recoveries.selectById(id).getRetroId()).getStatus());Long replacement=service.create(req(),1L);assertNotEquals(id,replacement);}
 @Test void pendingFormalIncomeAmendmentsCannotBeDeductedAgainThroughPayroll(){HrmSalaryMonthRecordDO b=target();assertServiceException(()->retro.create(new HrmPayrollRetroReqVO().setBatchId(b.getId()).setPaymentId(payment.getId()).setCorrectedIncome(n("8000")).setEvidence("不能重复抵减").setRequestKey(UUID.randomUUID().toString()),1L),PAYROLL_RECOVERY_TAX_UNMATCHED);Long id=approved();service.confirm(receipt(id),3L);Long prior=recoveries.selectById(id).getRetroId();Long next=retro.create(new HrmPayrollRetroReqVO().setBatchId(b.getId()).setPaymentId(payment.getId()).setPriorRetroId(prior).setCorrectedIncome(n("9000")).setEvidence("已收回后的独立补发").setRequestKey(UUID.randomUUID().toString()),1L);assertEquals(0,n("1000").compareTo(retros.selectById(next).getDelta()));assertEquals(0,n("8000").compareTo(retros.selectById(next).getOriginalIncome()));}
 @Test void paymentAndEntityScopeAndUnrelatedCorrectionAreEnforced(){doThrow(cn.iocoder.yudao.framework.common.exception.util.ServiceExceptionUtil.exception(PAYROLL_ENTITY_INVALID)).when(scope).check(any(),eq("READ"),eq(7L));assertServiceException(()->service.create(req(),7L),PAYROLL_ENTITY_INVALID);corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setPaymentId(999L));assertServiceException(()->service.create(req(),1L),PAYROLL_RECOVERY_INVALID);assertTrue(recoveries.selectList().isEmpty());assertTrue(retros.selectList().isEmpty());}
 @Test void sequentialRecoveryUsesIncrementalAmendmentAndCannotReuseBankReceipt(){Long first=approved();service.confirm(receipt(first),3L);Long priorRetro=recoveries.selectById(first).getRetroId();corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setStatus("SUPERSEDED"));HrmPayrollTaxCorrectionDO second=JsonUtils.parseObject(JsonUtils.toJsonString(correction),HrmPayrollTaxCorrectionDO.class).setId(null).setPriorCorrectionId(correction.getId()).setVersion(2).setIncome(n("7000"));second.setTaxpayerKey("recovery-person");corrections.insert(second);HrmPayrollWageRecoveryReqVO next=req().setPriorRetroId(priorRetro).setCorrectedIncome(n("7000")).setTaxCorrectionIds(Collections.singletonList(second.getId()));Long id=service.create(next,1L);service.review(id,true,"接续核实",2L);assertServiceException(()->service.confirm(receipt(id).setAmount(n("1000")),3L),PAYROLL_RECOVERY_INVALID);service.confirm(receipt(id).setAmount(n("1000")).setReference("recovery-receipt-002"),3L);assertEquals(0,n("7000").compareTo((BigDecimal)service.baseline(payment.getId(),1L).get("income")));}
 @Test void staleEntitlementApprovalCannotOverwriteCompetingApprovedVersion(){Long id=service.create(req(),1L);retros.insert(new HrmPayrollRetroDO().setPaymentId(payment.getId()).setEmployeeId(employeeId).setEntityId(10L).setBatchId(999L).setVersion(2).setStatus("APPROVED").setCorrectedIncome(n("11000")).setDelta(n("1000")).setRequestKey("competing-version"));assertServiceException(()->service.review(id,true,"旧基线",2L),PAYROLL_VERSION_CONFLICT);assertEquals("PENDING",recoveries.selectById(id).getStatus());}
 @Test void recoveryCanAllocateAcrossOriginalAndLaterSettledSupplementCashYears(){
  HrmSalaryMonthRecordDO later=target().setStatus(17).setMonth(9).setStartTime(LocalDate.of(2026,9,1).atStartOfDay()).setEndTime(LocalDate.of(2026,9,30).atStartOfDay()).setExpectedPaymentDate(LocalDate.of(2026,9,30));batches.updateById(later);
  HrmPayrollRetroDO previous=new HrmPayrollRetroDO().setEntityId(10L).setBatchId(later.getId()).setEmployeeId(employeeId).setPaymentId(payment.getId()).setVersion(1).setOriginalIncome(n("10000")).setCorrectedIncome(n("11000")).setDelta(n("1000")).setStatus("APPROVED").setSettlementMode("PAYROLL").setRequestKey("previous-paid-retro");retros.insert(previous);
  HrmSalaryMonthEmployeeRecordDO laterSalary=salary("11000","9900",2026);laterSalary.getOptionValues().add(new HrmSalaryMonthEmployeeRecordDO.OptionValue().setCode(10901).setValue(n("1000")));
  HrmPayrollRunDO laterRun=new HrmPayrollRunDO().setMonthRecordId(later.getId()).setVersion(1).setInputSnapshot(JsonUtils.toJsonString(Collections.singletonMap("retroSources",Collections.singletonList(previous)))).setRuleSnapshot("{}").setResultSnapshot(JsonUtils.toJsonString(Collections.singletonList(laterSalary)));runs.insert(laterRun);
  HrmPayrollPaymentDO laterPayment=new HrmPayrollPaymentDO().setMonthRecordId(later.getId()).setRunId(laterRun.getId()).setEmployeeId(employeeId).setEmployeeName("后续实发员工").setBankAccount("test-later-bank").setAmount(n("9900")).setStatus("SUCCESS").setAttempt(1).setValueDate(LocalDate.of(2026,9,30));payments.insert(laterPayment);
  HrmPayrollTaxPolicyDO laterPolicy=new HrmPayrollTaxPolicyDO().setEntityId(10L).setYear(2026).setVersion(1).setTaxRegistrationNumber("tax-agent").setStatus("APPROVED");policies.insert(laterPolicy);
  corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setIncome(n("8500")));HrmPayrollTaxCorrectionDO additional=JsonUtils.parseObject(JsonUtils.toJsonString(correction),HrmPayrollTaxCorrectionDO.class).setId(null).setPaymentId(laterPayment.getId()).setRunId(laterRun.getId()).setValueDate(laterPayment.getValueDate()).setPolicyId(laterPolicy.getId()).setIncome(n("10500")).setSourceDigest(HrmPayrollTaxCorrectionService.digest(payments.selectById(laterPayment.getId()),runs.selectById(laterRun.getId())));additional.setTaxpayerKey("recovery-person");corrections.insert(additional);
  Long id=service.create(req().setPriorRetroId(previous.getId()).setCorrectedIncome(n("9000")).setTaxCorrectionIds(Arrays.asList(correction.getId(),additional.getId())),1L);service.review(id,true,"按两笔实发的原年度核实分配",2L);service.confirm(receipt(id),3L);List<HrmPayrollWageRecoveryService.Allocation> allocation=JsonUtils.parseArray(recoveries.selectById(id).getAllocationSnapshot(),HrmPayrollWageRecoveryService.Allocation.class);assertEquals(new HashSet<>(Arrays.asList(2025,2026)),new HashSet<>(Arrays.asList(allocation.get(0).getCashYear(),allocation.get(1).getCashYear())));assertEquals(0,n("2000").compareTo(allocation.stream().map(HrmPayrollWageRecoveryService.Allocation::getIncomeReduction).reduce(BigDecimal.ZERO,BigDecimal::add)));assertEquals(0,n("9000").compareTo(retro.baseline(payment,retros.selectById(recoveries.selectById(id).getRetroId()))));
 }

 @Test void aLaterAmendmentCannotSkipAnEarlierUnsettledIncomeReduction(){corrections.updateById(new HrmPayrollTaxCorrectionDO().setId(correction.getId()).setStatus("SUPERSEDED"));HrmPayrollTaxCorrectionDO next=JsonUtils.parseObject(JsonUtils.toJsonString(correction),HrmPayrollTaxCorrectionDO.class).setId(null).setPriorCorrectionId(correction.getId()).setVersion(2).setIncome(n("7000"));next.setTaxpayerKey("recovery-person");corrections.insert(next);assertServiceException(()->service.create(req().setCorrectedIncome(n("9000")).setTaxCorrectionIds(Collections.singletonList(next.getId())),1L),PAYROLL_RECOVERY_TAX_UNMATCHED);assertTrue(recoveries.selectList().isEmpty());}

 @Test void concurrentIdenticalRequestReturnsOneCaseAndOneEntitlement() throws Exception {HrmPayrollWageRecoveryReqVO request=req();java.util.concurrent.ExecutorService executor=java.util.concurrent.Executors.newFixedThreadPool(2);try{java.util.concurrent.Future<Long> a=executor.submit(()->service.create(request,1L)),b=executor.submit(()->service.create(request,1L));assertEquals(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS));assertEquals(1,recoveries.selectCount());assertEquals(1,retros.selectCount());assertEquals(1,events.selectCount());}finally{executor.shutdownNow();}}
 @Test void concurrentRequestsCannotClaimTheSameFormalIncomeReduction() throws Exception {java.util.concurrent.ExecutorService executor=java.util.concurrent.Executors.newFixedThreadPool(2);java.util.concurrent.Callable<Boolean> submit=()->{try{service.create(req(),1L);return true;}catch(cn.iocoder.yudao.framework.common.exception.ServiceException conflict){assertEquals(PAYROLL_RECOVERY_INVALID.getCode(),conflict.getCode());return false;}};try{java.util.concurrent.Future<Boolean> a=executor.submit(submit),b=executor.submit(submit);assertNotEquals(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS));assertEquals(1,recoveries.selectCount());assertEquals(1,retros.selectCount());}finally{executor.shutdownNow();}}

}
